/* number words that follow the content (chambers and gems may grow) */
function axWord(){return {5:'الخمس',6:'الستّ',7:'السبع',8:'الثماني'}[AXES.length]||n2a(AXES.length);}
function gemsWord(n){var w={27:'سبعٌ وعشرون',28:'ثمانٍ وعشرون',29:'تسعٌ وعشرون',30:'ثلاثون',31:'إحدى وثلاثون',32:'اثنتان وثلاثون',33:'ثلاثٌ وثلاثون',34:'أربعٌ وثلاثون',35:'خمسٌ وثلاثون',36:'ستٌّ وثلاثون'}[n];return w?w+' جوهرةً':n2a(n)+' جوهرة';}
function qTotalWord(n){return {15:'خمسة عشر سؤالًا',18:'ثمانية عشر سؤالًا',21:'واحدٌ وعشرون سؤالًا',24:'أربعةٌ وعشرون سؤالًا'}[n]||n2a(n)+' سؤالًا';}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\u27e8/g,'&#10216;').replace(/\u27e9/g,'&#10217;');}
function gem(on){return '<span class="gem'+(on?' on':'')+'">'+STAR+'</span>';}

